// TinyFonts - optional integration with TinyGPU.
//
// TinyFonts itself does not depend on TinyGPU. Include this header only in
// projects that use TinyGPU:
//
//   #include <TinyGPU.h>
//   #include <TinyFonts/Integrations/TinyGPU.h>
//   #include <TinyFonts/Fonts/Lato16.h>                  // bundled, or generated by the converter
//
//   tinyfonts::TinyGPUFont<RGB565> lato16(tinyfonts::Lato16);
//   framebuffer.setFont(lato16);             // now TinyGPU drawing uses TinyFonts
//   framebuffer.drawText(8, 8, "Grüße", RGB565::fromRGB(255, 255, 0));
//
// TinyGPUFont implements tinygpu::IFont, so every TinyGPU surface (Surface,
// FrameBuffer, sprites) can use it through setFont()/drawText(). Behaviour:
//   - Text is alpha-blended over what is already on the surface, unless
//     `opaque` is true, in which case the text box is filled with `background`
//     first.
//   - `scale` is an integer multiplier: each font pixel becomes a scale x scale
//     block. TinyFonts glyphs are sized at conversion time, so use a larger
//     font size for smooth large text.
//   - `spacing` and `lineSpacing` are accepted but ignored: TinyFonts uses each
//     glyph's own advance and the font's line gap.
//   - The surface clip rectangle (pushClipRect) is honoured.
//   - Fonts are always proportional; setProportional() has no effect.
//   - Multi-line text honours '\n'. Use drawWrapped() for word wrapping, since
//     IFont::drawText has no width parameter.
//
// Colours are handled through getRed/getGreen/getBlue and fromRGB, so the
// template works with the TinyGPU colour types that provide those (RGB565 is
// tested).

#pragma once

#include <stddef.h>
#include <stdint.h>

#include <TinyGPU.h>

#include "../../TinyFonts.h"

namespace tinyfonts {

namespace detail {

inline const char* textEnd(const char* text) {
  if (text == nullptr) return nullptr;
  while (*text) ++text;
  return text;
}

}  // namespace detail

/**
 * @brief FontDisplay that writes TinyFonts coverage into a TinyGPU surface.
 *
 * Each pixel is alpha-blended over the background. Used internally by TinyGPUFont.
 */
template <typename RGB_T = tinygpu::RGB565>
class TinyGPUDisplay : public FontDisplay {
 public:
  /// Creates a display that draws into target.
  explicit TinyGPUDisplay(tinygpu::ISurface<RGB_T>& target) : target_(target) {}

  /// Sets the text origin on the surface, the colour and the integer scale. Call before each use.
  void begin(int originX, int originY, RGB_T color, uint8_t scale) {
    originX_ = originX;
    originY_ = originY;
    color_ = color;
    scale_ = scale == 0 ? 1 : scale;
  }

  /// Blends one coverage value into the target at the scaled position, respecting bounds and the clip rectangle.
  void drawPixel(int x, int y, uint8_t coverage) override {
    if (coverage == 0) return;
    for (int dy = 0; dy < scale_; ++dy) {
      for (int dx = 0; dx < scale_; ++dx) {
        const int px = originX_ + x * scale_ + dx;
        const int py = originY_ + y * scale_ + dy;
        if (px < 0 || py < 0 || px >= static_cast<int>(target_.width()) ||
            py >= static_cast<int>(target_.height())) {
          continue;
        }
        if (!target_.isClipVisible(px, py)) continue;
        if (coverage == 255) {
          target_.setPixel(px, py, color_);
        } else {
          target_.setPixel(px, py,
                           blend(target_.getPixel(px, py), color_, coverage));
        }
      }
    }
  }

  // Linear blend: fg * a + bg * (1 - a), with a in 0..255.
  /// Blends fg over bg by a (0 = bg only, 255 = fg only).
  static RGB_T blend(RGB_T bg, RGB_T fg, uint8_t a) {
    return RGB_T::fromRGB(mix(bg.getRed(), fg.getRed(), a),
                          mix(bg.getGreen(), fg.getGreen(), a),
                          mix(bg.getBlue(), fg.getBlue(), a));
  }

 private:
  static uint8_t mix(uint8_t bg, uint8_t fg, uint8_t a) {
    return static_cast<uint8_t>((bg * (255 - a) + fg * a + 127) / 255);
  }

  tinygpu::ISurface<RGB_T>& target_;
  int originX_ = 0;
  int originY_ = 0;
  RGB_T color_;
  int scale_ = 1;
};

/**
 * @brief A TinyFonts font usable wherever TinyGPU expects an IFont.
 *
 * Pass it to framebuffer.setFont() and use drawText(). drawWrapped() adds word wrap.
 */
template <typename RGB_T = tinygpu::RGB565>
class TinyGPUFont : public tinygpu::IFont<RGB_T> {
 public:
  /// Wraps a TinyFonts font. The font data is not copied.
  explicit TinyGPUFont(const Font& font) : font_(font) {}

  // IFont interface -------------------------------------------------------

  /// Draws text at (x, y) as defined by tinygpu::IFont. Honours opaque, scale and the clip rectangle; spacing and lineSpacing are ignored.
  void drawText(tinygpu::ISurface<RGB_T>& target, int16_t x, int16_t y,
                const char* text, RGB_T foreground, RGB_T background,
                bool opaque = false, uint8_t scale = 1, uint8_t spacing = 1,
                uint8_t lineSpacing = 1) const override {
    (void)spacing;
    (void)lineSpacing;
    drawBlock(target, x, y, text, 0, foreground, background, opaque, scale);
  }

  /// Width of the longest line in pixels, multiplied by scale.
  size_t measureTextWidth(const char* text, uint8_t scale = 1,
                          uint8_t spacing = 1) const override {
    (void)spacing;
    return scaled(measure(text, 0).width, scale);
  }

  /// Height of the text block in pixels, multiplied by scale.
  size_t measureTextHeight(const char* text, uint8_t scale = 1,
                           uint8_t lineSpacing = 1) const override {
    (void)lineSpacing;
    return scaled(measure(text, 0).height, scale);
  }

  /// Line height in pixels at the given scale.
  size_t getHeight(uint8_t scale) const override {
    return scaled(font_.lineHeight(), scale);
  }

  /// No-op: TinyFonts fonts are always proportional.
  void setProportional(bool proportional) override { (void)proportional; }
  /// Always true.
  bool isProportional() const override { return true; }

  // Extensions -------------------------------------------------------------

  /// Draws text wrapped to maxWidth pixels at the given scale. Returns the drawn height in pixels. maxWidth <= 0 disables wrapping.
  size_t drawWrapped(tinygpu::ISurface<RGB_T>& target, int16_t x, int16_t y,
                     int maxWidth, const char* text, RGB_T foreground,
                     RGB_T background = RGB_T(), bool opaque = false,
                     uint8_t scale = 1) const {
    return drawBlock(target, x, y, text, maxWidth, foreground, background,
                     opaque, scale);
  }

  /// Size of the text when wrapped to maxWidth pixels at the given scale.
  TextBox measureWrapped(const char* text, int maxWidth, uint8_t scale = 1) const {
    TextBox box = measure(text, maxWidth);
    const int s = scale == 0 ? 1 : scale;
    box.width *= s;
    box.height *= s;
    return box;
  }

  /// The wrapped TinyFonts font.
  const Font& font() const { return font_; }

 private:
  static size_t scaled(int value, uint8_t scale) {
    return static_cast<size_t>(value) * (scale == 0 ? 1 : scale);
  }

  TextBox measure(const char* text, int maxWidth) const {
    if (text == nullptr) return TextBox();
    return measureText(font_, text, detail::textEnd(text), maxWidth);
  }

  // Shared drawing path. Returns the height drawn, in pixels.
  size_t drawBlock(tinygpu::ISurface<RGB_T>& target, int16_t x, int16_t y,
                   const char* text, int maxWidth, RGB_T foreground,
                   RGB_T background, bool opaque, uint8_t scale) const {
    if (text == nullptr) return 0;
    const int s = scale == 0 ? 1 : scale;
    const TextBox box = measure(text, maxWidth / s);

    if (opaque) {
      fillBox(target, x, y, box.width * s, box.height * s, background);
    }

    TinyGPUDisplay<RGB_T> display(target);
    display.begin(x, y, foreground, static_cast<uint8_t>(s));
    TextRenderer renderer(font_, display);
    renderer.drawText(0, 0, text, maxWidth / s);
    return static_cast<size_t>(box.height) * s;
  }

  // Fills a rectangle, clipped to the surface bounds.
  static void fillBox(tinygpu::ISurface<RGB_T>& target, int x, int y, int w,
                      int h, RGB_T color) {
    int x0 = x < 0 ? 0 : x;
    int y0 = y < 0 ? 0 : y;
    int x1 = x + w;
    int y1 = y + h;
    if (x1 > static_cast<int>(target.width())) x1 = static_cast<int>(target.width());
    if (y1 > static_cast<int>(target.height())) y1 = static_cast<int>(target.height());
    if (x1 <= x0 || y1 <= y0) return;
    target.fillRect(x0, y0, x1 - x0, y1 - y0, color);
  }

  Font font_;
};

}  // namespace tinyfonts
